class AiProxyService < Formula
  desc "Pool AI subscriptions and API keys behind one endpoint with an admin panel"
  homepage "https://github.com/veildawn/ai-proxy-releases"

  livecheck do
    url :stable
    strategy :github_latest
  end

  # Prebuilt release archives; the version is parsed from the url. This file is
  # regenerated by the Release workflow in veildawn/ai-proxy-releases on every
  # release — bump it by cutting a release, never by hand.
  on_macos do
    on_arm do
      url "https://github.com/veildawn/ai-proxy-releases/releases/download/v0.17.93/ai-proxy-service_0.17.93_darwin_arm64.tar.gz"
      sha256 "bacaf1371c5d12aeda17857d54ce8cf225221494afb9b4c053d867234b232321"
    end
    on_intel do
      url "https://github.com/veildawn/ai-proxy-releases/releases/download/v0.17.93/ai-proxy-service_0.17.93_darwin_amd64.tar.gz"
      sha256 "c484663c194cf10b5debf0449444ad6ef6fe2c831dcc7818d636f136cad9ab54"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/veildawn/ai-proxy-releases/releases/download/v0.17.93/ai-proxy-service_0.17.93_linux_arm64.tar.gz"
      sha256 "320e020efadc9f3f67007d39198c794da9513aefd78d8c1be3e2c310abfdae40"
    end
    on_intel do
      url "https://github.com/veildawn/ai-proxy-releases/releases/download/v0.17.93/ai-proxy-service_0.17.93_linux_amd64.tar.gz"
      sha256 "d57a62f59d27d9b886594f1f4b6b853eca196cd172893ea3c78930c61d8fc934"
    end
  end

  # Everything the app writes lives under var/ai-proxy-service — the same
  # single-DATA_DIR layout install.sh uses: .env is loaded from the working
  # directory, secrets.env and setup-token are written beside config.yaml, and
  # logging.dir + chat assets default to ./data/ relative to it.
  def install
    bin.install "ai-proxy-service"
    (var/"ai-proxy-service").install "config.example.yaml", ".env.example"
  end

  def post_install
    dir = var/"ai-proxy-service"
    # Seeded once and never overwritten on upgrade — config.yaml may have been
    # edited by hand (same rule as install.sh).
    unless (dir/"config.yaml").exist?
      cp dir/"config.example.yaml", dir/"config.yaml"
      # The binary lives in a versioned keg owned by brew; an in-place
      # self-update would swap it under the old version's Cellar path and the
      # next `brew upgrade` would silently revert it. brew is the update path.
      inreplace dir/"config.yaml", "  allow_self_update: true", "  allow_self_update: false"
    end
    unless (dir/".env").exist?
      cp dir/".env.example", dir/".env"
      inreplace dir/".env", "APP_ENV=development", "APP_ENV=production"
    end
  end

  service do
    run [opt_bin/"ai-proxy-service", "serve", "--config", var/"ai-proxy-service/config.yaml"]
    working_dir var/"ai-proxy-service"
    keep_alive true
    environment_variables APP_ENV: "production"
    log_path var/"log/ai-proxy-service.out.log"
    error_log_path var/"log/ai-proxy-service.err.log"
  end

  def caveats
    <<~EOS
      Point it at a database first — database.dsn in
        #{var}/ai-proxy-service/config.yaml
      or DATABASE_URL in
        #{var}/ai-proxy-service/.env

      Then start it:
        brew services start ai-proxy-service
      or run it by hand:
        ai-proxy-service serve --config #{var}/ai-proxy-service/config.yaml

      Finish setup at http://localhost:8080/setup with the one-time token from:
        cat #{var}/ai-proxy-service/setup-token

      Update with: brew upgrade ai-proxy-service
      Starting runs database migrations; the in-app self-update is disabled on
      purpose — brew owns this binary.
    EOS
  end

  test do
    assert_equal version.to_s, shell_output("#{bin}/ai-proxy-service version").strip
  end
end
